probe[args___]:=AsymptoticAnalysis`Private`catch[AsymptoticAnalysis`Private`fourierComposeBlock[args]];
actual=Module[{x,y,s,r},
 s=AsymptoticFourierInverse[x+x^2,{x,0},{y,7},"MaxTerms"->7];
 If[Head[s]=!=GeneralizedSeries,s,
 r=FourierInverseResidual[s,Automatic,"MaxTerms"->7];
 {Head[s],Expand[Normal[s]-(y-y^2+2y^3-5y^4+14y^5-42y^6)],
  If[AssociationQ[r],{r["ZeroBelowCutoff"],r["ResidualBlocks"],r["RelativeCutoff"]},r]}]];
expected={GeneralizedSeries,0,{True,{},6}};
accepted=TrueQ[SameQ[actual,expected]];
Print["ASYMPTOTIC_PORTABLE_ACTUAL_BEGIN"];
Print[ToString[InputForm[actual]]];
Print["ASYMPTOTIC_PORTABLE_ACTUAL_END"];
Print["ASYMPTOTIC_PORTABLE_EXPECTED_BEGIN"];
Print[ToString[InputForm[expected]]];
Print["ASYMPTOTIC_PORTABLE_EXPECTED_END"];
Print["ASYMPTOTIC_PORTABLE_RESULT\tfourier-public-residual-budget-seven\t",If[accepted,"Success","Failure"]];
Exit[If[accepted,0,1]];

